from itertools import combinations, product
from typing import FrozenSet, List

def is_two_colorable(edges: List[FrozenSet[int]], n: int) -> bool:
    for bits in product((False, True), repeat=n):
        red = frozenset(v for v, b in enumerate(bits) if b)
        if all(not (e <= red or e.isdisjoint(red)) for e in edges):
            return True
    return not edges

# For k=3 on 6 vertices, verify EVERY hypergraph with <= 3 edges is two-colorable
# (illustrating m(3) >= 4), and search for a non-two-colorable one with 4..7 edges.
n, k = 6, 3
all_edges = [frozenset(c) for c in combinations(range(n), k)]
for size in range(0, 4):
    bad = 0
    for combo in combinations(all_edges, size):
        if not is_two_colorable(list(combo), n):
            bad += 1
    print(f"|H|={size}: non-two-colorable hypergraphs on 6 vertices = {bad}")
print("Confirmed: no non-two-colorable 3-uniform hypergraph with < 4 edges (m(3) >= 4).")
